import re
import os
import time
import logging
from taf.transport.ssh import ssh


class config(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self.csn = ssh()

    def create_connection(self, ip_address, user_name, password):
        """
        Creates session to test machine that contains STC client.

        :param ip_address: ip address of test machine
        :param user_name: user name for SSH connection
        :param password: password for SSH connection
        """
        logging.info("Resetting cache")
        self.csn.reset_cache()
        self._host_pc_con = self.csn.connect_to(ip_address, user_name,
                                                password)
        self._tcl_shell = self._host_pc_con.invoke_shell()
        self._tcl_shell.send("tclsh\n")
        time.sleep(1)
        self._tcl_shell.recv(1024)

    def upload_config_file(self, local_path, remote_path):
        """
        Uploads CFG file from local to test machine.

        :param local_path: path to local CFG file
        :param remote_path: path to remote CFG file
        :return: Returns true if run successfully and false otherwise
        """
        logging.info("Upload file from local to test machine")
        self.csn.upload_file(local_path, remote_path, self._host_pc_con)
        output = self.csn.file_exists(remote_path, self._host_pc_con)
        return output

    @staticmethod
    def modify_config_file(config_file, **kwargs):
        """
        Modifies CFG file with provided parameters.
        Replace all the same parameter's value in CFG file.
        e.g
        -ColumnUnits "0"    ->    -ColumnUnits "123"
        -ColumnUnits "5"    ->    -ColumnUnits "123"

        :param config_file: path to CFG file
        :param kwargs: parameters for modifying CFG file
        """
        with open(config_file, 'r') as fh:
            config_data = fh.read()
            for param_name, new_value in kwargs.items():
                reg_str = "(\-%s\s+)([\w\"\$\{].*[\w\"\$\}])" % param_name
                res = re.findall(reg_str, config_data)
                new_value = str(new_value)
                for name, value in res:
                    if '"' in value:
                        replaced_value = '"' + new_value + '"'
                    else:
                        replaced_value = new_value
                    old_str = name + value
                    replaced_str = name + replaced_value
                    config_data = config_data.replace(old_str, replaced_str)
        with open(config_file, 'w') as out_fh:
            out_fh.write(config_data)

    def start_to_send_packet(self, config_file):
        """
        Starts send packets in STC.

        :param config_file: path to CFG file
        """
        self.execute_tcl_config_file(config_file)

    def execute_tcl_config_file(self, config_file):
        """
        Starts STC test automatically by running tcl scripts.

        :param config_file: path to CFG file
        :return: Returns output contents
        """
        command = "tclsh {config_file}".format(config_file=config_file)
        output = self.csn.execute(command, self._host_pc_con)
        logging.info(command + '\n' + output)
        return output

    def execute_tcl_command(self, command):
        """
        execute tcl command on test center client

        :param command: tcl command
        :return Returns output contents.
        """
        self._tcl_shell.send(command + "\n")
        time.sleep(1)
        raw_out = self._tcl_shell.recv(1024)
        output = '\n'.join(raw_out.split('\r\n')[1:-1]).strip() if raw_out else ''
        logging.info(command + '\n' + output)
        return output

    def translate_data_format(self, tool_path, db_file_path, output_path,
                              template_path):
        """
        Translate data from DB to CSV/PDF/HTML/JPEG with result reporter tool.

        :param tool_path: translate tool, e.g /xxx/ResultsReporterCLI.sh
        :param db_file_path: src DB file, e.g /yyy/MyResults.db
        :param output_path: dst output file, e.g /yyy/MyResults.csv
        :param template: template file, e.g /xxx/CustomStats.rtp
        :return: Returns output contents
        """
        command = "{0} -o {1} -f csv -d {2} -t {3}".format(tool_path,
                                                           db_file_path,
                                                           output_path,
                                                           template_path)

        output = self.csn.execute(command, self._host_pc_con)
        logging.info(command + '\n' + output)
        return output

    def download_file(self, remote_file, local_file):
        """
        Downloads file from test machine to local.

        :param remote_file: path to remote file
        :param local_file: path to local file
        """
        logging.info("Downloads file from test machine to local")
        self.csn.download_file(remote_file, local_file, self._host_pc_con)

        if not os.path.exists(local_file):
            raise Exception("File '{}' doesn't exist.".format(local_file))

    def __del__(self):
        if hasattr(self, '_host_pc_con'):
            self.csn.disconnect(self._host_pc_con)
